<script>
 import ResearchPage from './ResearchPage.svelte';
 import DefiantEvidenceExplorer from './DefiantEvidenceExplorer.svelte';
 import ResearchToolbar from './ResearchToolbar.svelte';
 import ResearchInspector from './ResearchInspector.svelte';
 import TalentIntake from './TalentIntake.svelte';
 import DefiantVideoInbox from './DefiantVideoInbox.svelte';
 import ResourceConfirmation from './ResourceConfirmation.svelte';
 import EvidenceConstraints from './EvidenceConstraints.svelte';
 import {onMount,onDestroy,untrack} from 'svelte';
 import GraphCanvas from './GraphCanvas.svelte';
 import Icon from './Icon.svelte';
 import DefiantPlanning from './DefiantPlanning.svelte';
 let {request,evidenceRequest,location,onNavigate=()=>{},onDirtyChange=()=>{},canEnable=false,onEnabled=()=>{}}=$props();
 let state=$state(null),graph=$state(null),loading=$state(true),busy=$state(''),error=$state(''),notice=$state('');
 let query=$state(''),positions=$state({}),planIds=$state([]),intakeText=$state(''),preview=$state(null),intent=$state(null),unknown=$state(false);
 const routeEdgeIds=$derived(location.routeEdgeIds||[]);
 let routeMessage=$state(''),intakeReset=$state(0),guidedSelection=$state(null);
 const sampleMode=$derived(location.sample==='demo');
 const journeyItems=$derived(sampleMode?(graph?.items||[]):(state?.items||[]));
 const journeyRegions=$derived(sampleMode?(graph?.regions||[]):(state?.regions||[]));
 const selectedCollaborators=$derived(journeyItems.filter(item=>item.kind==='person'&&item.id!==current?.id&&journeyItems.some(edge=>edge.from===(location.artistId||current?.id)&&edge.to===item.id||edge.to===(location.artistId||current?.id)&&edge.from===item.id)));
 const journeyArtists=$derived(journeyItems.filter(item=>item.kind==='artist'&&(!location.regionId||item.regionId===location.regionId)));
 const selectedRoute=$derived(state?.graph.edges.find(edge=>edge.id===selected&&edge.kind==='route'));
 const routeEdges=$derived(routeEdgeIds.map(id=>state?.graph.edges.find(edge=>edge.id===id)).filter(Boolean));
 const routeAvailable=$derived(routeEdges.length===routeEdgeIds.length&&routeEdges.every((edge,index)=>!index||routeEdges[index-1].to===edge.from));
 function itemName(id){return journeyItems.find(node=>node.id===id)?.name||'Unavailable reference';}
 function addRouteEdge(){const edge=selectedRoute,last=routeEdges.at(-1);if(!edge)return;if(!routeAvailable){routeMessage='Clear the unavailable route before adding another step.';return;}if(routeEdgeIds.includes(edge.id)){routeMessage='This route already includes that step.';return;}if(last&&last.to!==edge.from){routeMessage='Choose a route starting at '+itemName(last.to)+', or clear this route to start another.';return;}if(routeEdgeIds.length>=16){routeMessage='A route can contain up to 16 steps.';return;}navigate({routeEdgeIds:[...routeEdgeIds,edge.id],savedViewId:''});routeMessage='';}
 function followRouteDestination(){if(selectedRoute)navigate({view:'map',query:'',focus:selectedRoute.to,selected:selectedRoute.to});}
 function shortlistRoute(){if(!routeAvailable)return;planIds=[...new Set([...planIds,...routeEdgeIds])];routeMessage='Route steps added to your shortlist.';}
 let inboxDirty=$state(false),resourceDirty=$state(false),intakeDirty=$state(false),planningDirty=$state(false),reportRequest=$state(0);
 $effect(()=>onDirtyChange(intakeDirty||planningDirty||resourceDirty||inboxDirty));
 let restoredView='';
 $effect(()=>{const id=location.savedViewId;const view=state?.views.find(v=>v.id===id);untrack(()=>{if(view&&restoredView!==id){positions=view.positions||{};planIds=view.planIds||[];restoredView=id;if(!location.routeEdgeIds?.length&&view.routeEdgeIds?.length)navigate({routeEdgeIds:view.routeEdgeIds});}});});
 let alive=true,sequence=0;
 let graphLoading=$state(false);
 const selected=$derived(location?.selected||''),focus=$derived(location?.focus||'');
 const filters=$derived({kinds:location.kinds||[],showExamples:location.showExamples!==false,...(query.trim()?{query:query.trim()}:{})});
 const activeFilters=$derived(Boolean(filters.kinds.length||!filters.showExamples));
 const visibleItems=$derived(journeyItems.filter(n=>(filters.showExamples||n.verification!=='example')&&(!filters.kinds.length||filters.kinds.includes(n.kind))));
 const visibleRegions=$derived(visibleItems.filter(n=>n.kind==='region'));
 $effect(()=>{query=location.query||'';});
 const current=$derived(graph?.selectedItem?.id===selected?graph.selectedItem:null),matches=$derived(graph?.matches||[]);
 const typeName={cluster:'Working group',region:'Region',artist:'Artist',signal:'Signal',person:'Collaborator',resource:'Resource',format:'Media concept',catalog:'Catalog reference',route:'Route',external:'External reference'};
 function changeView(view){if(inboxDirty||planningDirty||intakeDirty||resourceDirty){error='Save or clear your working text before changing views.';return;}navigate({view,...(view!=='report'?{reportId:''}:{}),...(view==='inbox'?{origin:'catalog',sample:'',...(sampleMode?{focus:'',selected:'',regionId:'',artistId:''}:{})}:view==='map'?{origin:'talent'}:sampleMode?{sample:'',focus:'',selected:'',regionId:'',artistId:''}:{})});}
 function buildReport(){if(inboxDirty||planningDirty||intakeDirty||resourceDirty){error='Save or clear your working text before starting a shortlist report.';return;}reportRequest++;}
 function navigate(next){onNavigate({...location,...next});}
 function select(id){const repeat=id===selected;const item=journeyItems.find(n=>n.id===id);navigate({view:'map',origin:'talent',...(item?.kind==='region'?{regionId:id,artistId:''}:item?.kind==='artist'?{regionId:item.regionId||location.regionId||'',artistId:id}:{}),query:'',selected:id,focus:['region','artist','signal','person','resource','cluster'].includes(item?.kind)?id:focus});query='';if(repeat)void loadGraph();}
 async function loadGraph(){
  if(location.view==='evidence'){sequence++;graphLoading=false;return;}
  const ticket=++sequence;error='';graphLoading=true;
  try{const q=new URLSearchParams({focusId:focus,selectedId:selected,query,...(sampleMode?{sample:'demo'}:{}),...(filters.kinds.length?{kinds:filters.kinds.join(',')}:{}),showExamples:String(filters.showExamples)});const value=await request('/graph?'+q);if(alive&&ticket===sequence)graph=value;}
  catch(failure){if(alive&&ticket===sequence)error=failure.message;}
  finally{if(alive&&ticket===sequence)graphLoading=false;}
 }
 async function load(){
  if(!state)loading=true;error='';
  try{const value=await request('');if(!alive)return;state=value;await loadGraph();}
  catch(failure){if(alive)error=failure.status===404&&canEnable?'':failure.message;}
  finally{if(alive)loading=false;}
 }
 $effect(()=>{focus;selected;location.view;location.sample;location.kinds;location.showExamples;location.query;untrack(()=>{if(state)void loadGraph();});});
 onMount(()=>{void load();});
 onDestroy(()=>{alive=false;sequence++;});
 async function enable(){
  if(busy)return;busy='enable';error='';
  try{await request('/enable',{method:'POST',body:'{}'});if(!alive)return;await onEnabled();await load();}
  catch(failure){if(alive)error=failure.message;}
  finally{if(alive)busy='';}
 }
 function editIntake(value){intakeText=value;preview=null;if(!unknown)intent=null;intakeDirty=Boolean(value.trim());}
 async function inspectIntake(kind){
  if(busy||unknown)return;busy='preview';error='';notice='';
  try{const input=kind==='demo'?{kind}:{kind,data:JSON.parse(intakeText)};const value=await request('/import-preview',{method:'POST',body:JSON.stringify(input)});if(!alive)return;preview=value;intent={...input,expectedRevision:value.expectedRevision,idempotencyKey:crypto.randomUUID()};intakeDirty=true;}
  catch(failure){if(alive)error=failure.message;}
  finally{if(alive)busy='';}
 }
 async function importPreview(){
  if(!intent||busy)return;busy='import';error='';notice='';
  try{await request('/import',{method:'POST',body:JSON.stringify(intent)});if(!alive)return;notice='References saved';preview=null;intent=null;unknown=false;intakeText='';intakeDirty=false;intakeReset++;await load();if(guidedSelection){navigate({view:'map',origin:'talent',sample:'',...guidedSelection,focus:guidedSelection.artistId,selected:guidedSelection.artistId});guidedSelection=null;}}
  catch(failure){if(!alive)return;error=failure.message;unknown=!(Number.isInteger(failure.status)&&failure.status>=400&&failure.status<500);}
  finally{if(alive)busy='';}
 }
 function restoreView(view){restoredView=view.id;positions=view.positions||{};planIds=view.planIds||[];navigate({view:'map',focus:view.focus||'',selected:view.selected||'',savedViewId:view.id,reportId:'',kinds:view.filters?.kinds||[],showExamples:view.filters?.showExamples!==false,query:view.filters?.query||'',routeEdgeIds:view.routeEdgeIds||[]});}
 async function planningSaved(ack){if(ack&&state)state={...state,revision:ack.revision};await load();}
 function previewGuided(data,selection){guidedSelection=selection;intakeText=JSON.stringify(data);void inspectIntake('owned');}
 function openSample(){if(intakeDirty||planningDirty||resourceDirty||inboxDirty){error='Save or clear your working text before opening the sample.';return;}navigate({view:'map',origin:'talent',sample:'demo',focus:'',selected:'',regionId:'',artistId:'',savedViewId:'',reportId:'',query:'',kinds:[],showExamples:true,routeEdgeIds:[]});}
 function togglePlan(id){if(sampleMode)return;planIds=planIds.includes(id)?planIds.filter(x=>x!==id):[...planIds,id];}
</script>
<ResearchPage label="Defiant strategy workspace">
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 {#if loading}<p role="status">Opening your strategy workspace…</p>
 {:else if !state}
  <div class="empty"><h2>A separate space for strategy</h2><p>Explore people, regional routes and evidence without changing your publishing brands.</p>{#if canEnable}<button class="primary" disabled={!!busy} onclick={enable}>{busy==='enable'?'Opening…':'Enable strategy for this organization'}</button>{:else}<p>This organization’s strategy workspace is unavailable.</p>{/if}</div>
 {:else}
 <nav aria-label="Defiant task views" class="research-task-navigation"><button class={{chosen:location.view==='inbox'}} onclick={()=>changeView('inbox')}>Catalog-led</button><button class={{chosen:location.view==='map'}} onclick={()=>changeView('map')}>Talent-led</button><button class={{chosen:location.view==='report'}} onclick={()=>changeView('report')}>Reports</button><button class={{chosen:location.view==='evidence'}} onclick={()=>changeView('evidence')}>Earnings &amp; receipts</button></nav>
 {#if location.view==='evidence'}<DefiantEvidenceExplorer request={evidenceRequest} {location} onNavigate={navigate}/>{:else if location.view==='inbox'}<DefiantVideoInbox state={state} {location} {request} onSaved={planningSaved} {onNavigate} onDirtyChange={value=>inboxDirty=value}/>{:else}
 {#if location.view==='map'}
 <ResearchToolbar label="Talent research controls"><div class="toolbar-title"><h2>Talent discovery</h2>{#if journeyItems.length}<small>{journeyRegions.length} regions · {journeyArtists.length} artists</small>{/if}</div>{#if journeyItems.length} <label>Region<select value={location.regionId||''} onchange={e=>{const id=e.currentTarget.value;navigate({origin:'talent',regionId:id,artistId:'',focus:id,selected:id});}}><option value="">All regions</option>{#each journeyRegions as region(region.id)}<option value={region.id}>{region.name}</option>{/each}</select></label><label>Artist<select value={location.artistId||''} onchange={e=>e.currentTarget.value?select(e.currentTarget.value):navigate({artistId:'',focus:location.regionId||'',selected:location.regionId||''})}><option value="">Choose an artist</option>{#each journeyArtists as artist(artist.id)}<option value={artist.id}>{artist.name}</option>{/each}</select></label><details class="reference-browser"><summary>Find references</summary>  <div class="rail"><label class="search"><Icon name="search"/><input aria-label="Find an artist, region or resource" placeholder="Find anything…" value={query} onchange={()=>navigate({query:query.trim(),savedViewId:''})} onkeydown={e=>{if(e.key==='Enter')navigate({query:query.trim(),savedViewId:''});}} oninput={e=>{query=e.currentTarget.value;void loadGraph();}}/></label><div class="graph-filters"><label>Show type<select aria-label="Graph reference type" value={filters.kinds[0]||''} onchange={e=>navigate({kinds:e.currentTarget.value?[e.currentTarget.value]:[],savedViewId:''})}><option value="">All types</option>{#each ['region','artist','signal','person','resource','catalog','format','external','route'] as kind(kind)}{#if journeyItems.some(n=>n.kind===kind)}<option value={kind}>{typeName[kind]}</option>{/if}{/each}</select></label>{#if journeyItems.some(n=>n.verification==='example')}<label class="example-toggle"><input type="checkbox" checked={filters.showExamples} onchange={e=>navigate({showExamples:e.currentTarget.checked,savedViewId:''})}/>Show sample references</label>{/if}{#if activeFilters}<button onclick={()=>navigate({kinds:[],showExamples:true,savedViewId:''})}>Clear filters</button>{/if}</div>{#if query}<div class="search-results">{#each matches as item(item.id)}<button onclick={()=>select(item.id)}><strong>{item.name}</strong><small>{typeName[item.kind]||item.kind}</small></button>{/each}{#if !matches.length}<p>No matches</p>{/if}</div>{/if}<h3>{visibleRegions.length?'REGIONS':'REFERENCES'} <span>{visibleRegions.length||visibleItems.length}</span></h3><button class:chosen={!focus} onclick={()=>navigate({focus:'',selected:''})}>{journeyRegions.length?'All regions':'All references'}</button>{#each visibleRegions as region(region.id)}<button class:chosen={focus===region.id} onclick={()=>select(region.id)}>{region.name}<Icon name="chevron" size={13}/></button>{/each}<details><summary>All references</summary>{#each visibleItems as item(item.id)}<button onclick={()=>select(item.id)}>{item.name}<small>{typeName[item.kind]||item.kind}</small></button>{/each}</details></div></details>{/if}{#if !sampleMode}<details><summary>Add an artist and evidence</summary>{#key intakeReset}<TalentIntake disabled={!!busy||unknown||Boolean(preview)} onPreview={previewGuided} onClear={()=>{intakeText='';preview=null;intent=null;intakeDirty=false;guidedSelection=null;}} onDirtyChange={value=>intakeDirty=value||Boolean(intakeText.trim())}/>{/key}<details><summary>Advanced JSON import</summary><div class="intake"><label>Reference data<textarea rows="5" value={intakeText} disabled={!!busy||unknown} oninput={e=>editIntake(e.currentTarget.value)} placeholder={'{"nodes":[],"edges":[],"evidence":[],"observations":[],"resources":[]}'}></textarea></label><button disabled={!!busy||unknown||!intakeText.trim()} onclick={()=>{guidedSelection=null;void inspectIntake('owned');}}>Preview import</button></div></details></details><button class="secondary" disabled={!!busy} onclick={openSample}>Explore a sample without importing</button>{/if}</ResearchToolbar>
 {#if sampleMode}<div class="sample-context"><strong>Sample exploration · read only</strong><span>Illustrative references, not verified people, rights or opportunities.</span><button onclick={()=>navigate({sample:'',focus:'',selected:'',regionId:'',artistId:''})}>Return to owned references</button></div>{/if}
 {#if notice}<p class="notice" role="status">{notice}</p>{/if}
 {#if preview&&!sampleMode}<section class="import-preview" aria-label="Reference import preview"><h3>{preview.kind==='demo'?'Sample references':'Your reference preview'}</h3><p>{Object.entries(preview.counts).map(([kind,count])=>`${count} ${kind}`).join(' · ')}</p>{#each preview.warnings as warning(warning)}<p>{warning}</p>{/each}<button class="primary" disabled={!!busy} onclick={importPreview}>{busy==='import'?'Saving…':unknown?'Retry same import':'Add these references'}</button>{#if !unknown}<button disabled={!!busy} onclick={()=>{preview=null;intent=null;intakeDirty=Boolean(intakeText.trim());}}>Cancel</button>{/if}</section>{/if}

 <div class="scene" class:has-selection={Boolean(current||selected)}>

  <section class="map-area" aria-label="Opportunity map"><div class="map-heading"><div><h2>{journeyItems.find(n=>n.id===focus)?.name||(journeyRegions.length?'Explore regions':'Start with an artist reference')}</h2></div>{#if focus}<button class="quiet" onclick={()=>navigate({focus:'',selected:''})}><Icon name="back"/>{journeyRegions.length?'All regions':'All references'}</button>{/if}</div>
   {#if graph?.nodes.length}<GraphCanvas nodes={graph.nodes} {positions} edges={graph.edges} selectedId={selected} onselect={select} onmove={(id,pos)=>{positions={...positions,[id]:pos};}} {planIds}/>{:else}<div class="empty">{#if activeFilters}<h3>No references match these filters</h3><p>Change the type or include sample references to see more of this neighborhood.</p><button onclick={()=>navigate({kinds:[],showExamples:true,savedViewId:''})}>Clear filters</button>{:else}<h3>Start with a real reference</h3><p>Use Add an artist and evidence above, or explore the sample without changing your workspace.</p>{/if}</div>{/if}
   {#if routeEdgeIds.length&&!sampleMode}<section class="route-builder" aria-label="Current route"><h3>Your route</h3>{#if !routeAvailable}<p role="alert">A route step is unavailable or the steps no longer connect. Clear this route or remove its last step to rebuild it. Working notes keep their original target.</p>{/if}<ol>{#each routeEdges as edge(edge.id)}<li><button onclick={()=>select(edge.id)}>{itemName(edge.from)} → {itemName(edge.to)}</button></li>{/each}</ol><button onclick={()=>{navigate({routeEdgeIds:routeEdgeIds.slice(0,-1),savedViewId:''});routeMessage='';}}>Remove last step</button><button onclick={()=>{navigate({routeEdgeIds:[],savedViewId:''});routeMessage='';}}>Clear route</button><button disabled={!routeAvailable} onclick={shortlistRoute}>Add route to shortlist</button><p>Working route · connections and availability still need checking.</p>{#if routeMessage}<p role="status">{routeMessage}</p>{/if}</section>{/if}
   {#if !sampleMode}<div class="plan-tray"><strong>Your shortlist <span>{planIds.length}</span></strong><div>{#each planIds as id(id)}<button onclick={()=>togglePlan(id)}>{journeyItems.find(n=>n.id===id)?.name||id} ×</button>{/each}{#if !planIds.length}<span>Add people, routes or ideas as you explore.</span>{/if}</div><button disabled={!planIds.length} onclick={buildReport}>Build a report</button><small>Save a view to retain your shortlist and layout.</small></div>{/if}
  </section>
  {#if current||selected}<ResearchInspector label="Selection details" selected={true}>{#if current}<div class="inspector-top"><span class="eyebrow">{typeName[current.kind]||current.kind}</span><button aria-label="Close details" onclick={()=>navigate({selected:''})}><Icon name="close"/></button></div><h2>{current.name}</h2>{#if activeFilters&&!visibleItems.some(n=>n.id===current.id)}<p>Selected reference is outside these filters.</p>{/if}<p>{current.subtitle}</p><span class="sample-tag">{current.verification==='example'?'Sample reference':current.verification==='user-reported'?'User-reported reference':current.verification==='working-selection'?'Working selection':'Unverified reference'}</span>{#if current.profile||current.description}<h3>Why this connection</h3><p>{current.profile||current.description}</p>{/if}{#if current.tags?.length}<div class="tags">{#each current.tags as tag(tag)}<span>{tag}</span>{/each}</div>{/if}
   {#if selectedRoute}<section class="route-step" aria-label="Selected route step"><p><strong>{itemName(selectedRoute.from)}</strong> → <strong>{itemName(selectedRoute.to)}</strong></p><button onclick={followRouteDestination}>Follow destination</button><button onclick={addRouteEdge}>Add to route</button>{#if routeMessage&&!routeEdges.length}<p role="status">{routeMessage}</p>{/if}{#if routeEdges.length&&routeEdges.at(-1).to!==selectedRoute.from&&!routeEdgeIds.includes(selectedRoute.id)}<p>This step does not continue from {itemName(routeEdges.at(-1).to)}.</p>{/if}</section>{/if}
   {#if current.sourceRegion}<p>Regional corridor origin: {journeyItems.find(n=>n.id===current.sourceRegion)?.name||current.sourceRegion}</p>{/if}{#if graph.relatedResources.length}<h3>Possible connections</h3>{#each graph.relatedResources as related(related.id)}<button class="related" onclick={()=>select(related.id)}>{related.name}<Icon name="arrow" size={15}/></button>{/each}{/if}
   {#if selectedCollaborators.length}<section aria-label="Referenced collaborators"><h3>Referenced collaborators</h3>{#each selectedCollaborators as person(person.id)}<button class="related" onclick={()=>select(person.id)}>Open collaborator: {person.name}<Icon name="arrow" size={15}/></button>{/each}</section>{/if}
   {#if current.contextual}<section aria-label="Contextual relationship"><p>This connection is shown for context. It is not a saved relationship or confirmed collaboration.</p><button onclick={()=>select(current.to)}>Open destination reference</button></section>{/if}
   <EvidenceConstraints record={current} resources={current.resource?[current.resource]:[]} observations={current.observations||[]} evidence={current.evidence||[]} />{#if !current.contextual&&!sampleMode}<button class="add-plan" onclick={()=>togglePlan(current.id)}>{planIds.includes(current.id)?'Remove from shortlist':'Add to shortlist'}</button>{/if}
   <details class="provenance"><summary>Reference details</summary>{#each current.evidence||[] as evidence(evidence.id)}<article><h3>{evidence.title}</h3>{#if evidence.sourceUrl}<a href={evidence.sourceUrl} target="_blank" rel="noopener noreferrer">Open source ↗</a>{/if}<p>{evidence.excerpt}</p><small>{evidence.method} · {evidence.verification} · Observed {evidence.observedAt||'time unknown'}</small></article>{/each}<p>Relationships and permissions must be checked before acting.</p><code>{current.sourceId||current.id}</code></details>
  {:else}<div class="empty-inspector"><Icon name="network" size={26}/><h2>{graphLoading?'Opening selection…':selected?'Reference unavailable':'Select a region'}</h2><p>{selected?'This selection is no longer available. Choose another reference or return to all regions.':'Choose a region to find an artist, explore a route and collect what matters.'}</p></div>{/if}<ResourceConfirmation resource={sampleMode?null:current?.resource} evidence={state.evidence} revision={state.revision} {request} onSaved={planningSaved} onDirtyChange={value=>resourceDirty=value}/></ResearchInspector>{/if}
 </div>{/if}{#if !sampleMode}<div id="strategy-planning"><DefiantPlanning {routeAvailable} {routeEdgeIds} {filters} {reportRequest} {state} {location} {planIds} {positions} {request} onSaved={planningSaved} onNavigate={navigate} onRestoreView={restoreView} onDirtyChange={value=>planningDirty=value}/></div>{/if}{/if}{/if}
</ResearchPage>
<style>
.research-task-navigation{flex-wrap:wrap}
.toolbar-title{margin-right:auto;min-width:150px}.toolbar-title h2{font-size:18px}.toolbar-title small{font-size:11px;color:var(--research-muted)}.reference-browser .rail{min-width:250px;max-width:420px;padding:12px 0}.rail h3{margin:14px 0 6px;font-size:12px;color:var(--research-muted)}.rail button,.related{width:100%;display:flex;justify-content:space-between;text-align:left;border:0;background:transparent}.rail button.chosen{background:var(--research-selected)}.rail small{font-size:11px;display:block}.search{display:flex;align-items:center;gap:8px}.search input{flex:1;min-width:0}.graph-filters{padding:10px 0;display:grid;gap:8px}.example-toggle{flex-direction:row;align-items:center}.intake{max-width:650px;padding:12px 0;display:grid;gap:10px}.intake textarea{font-family:monospace}.sample-context{padding:8px var(--research-space);display:flex;flex-wrap:wrap;align-items:center;gap:10px;font-size:12px;background:var(--research-selected);border-bottom:1px solid var(--research-line)}.notice,.error{margin:10px var(--research-space)}.import-preview{padding:var(--research-space);background:var(--research-surface);border-bottom:1px solid var(--research-line)}.scene{display:grid;grid-template-columns:minmax(0,1fr);align-items:start;min-width:0}.scene.has-selection{grid-template-columns:minmax(0,1fr) minmax(260px,300px)}.scene :global(.research-inspector){border-left:1px solid var(--research-line)}.map-area{display:flex;flex-direction:column;min-width:0;grid-column:1;grid-row:1}.map-heading{padding:12px var(--research-space);display:flex;justify-content:space-between;align-items:center;gap:12px}.map-heading h2{font-size:18px}.inspector-top{display:flex;align-items:center;justify-content:space-between}.eyebrow{font-size:10px;letter-spacing:.1em;color:var(--research-muted)}.sample-tag{font-size:11px;display:inline-block;padding:3px 6px;background:var(--research-selected);border-radius:4px}.tags{display:flex;flex-wrap:wrap;gap:5px;margin:10px 0}.tags span{font-size:11px;background:var(--research-canvas);padding:3px 6px;border-radius:4px}.add-plan{width:100%;margin:12px 0}.provenance{margin-top:12px;font-size:12px}.empty,.empty-inspector{padding:28px var(--research-space);min-height:240px}.empty h3{font-size:20px}.empty p{max-width:460px;color:var(--research-muted)}.plan-tray{margin:12px var(--research-space);padding:10px;border:1px solid var(--research-line);border-radius:8px;display:flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:12px}.plan-tray>div{flex:1;display:flex;flex-wrap:wrap;gap:5px}.plan-tray small{flex-basis:100%;color:var(--research-muted)}.route-builder{margin:12px var(--research-space);padding:12px;border:1px solid var(--research-line);border-radius:8px}.route-builder button,.route-step button{margin:4px}.route-step{padding:10px 0;border-bottom:1px solid var(--research-line)}
@media(max-width:900px){.scene.has-selection{grid-template-columns:minmax(0,1fr)}.scene :global(.research-inspector){grid-column:1;grid-row:2;border-left:0;border-top:1px solid var(--research-line)}.map-area{grid-column:1;grid-row:1}.toolbar-title{width:100%;margin:0}.map-heading{padding-block:10px}}
</style>
